}

{
  "decision": "human_review",
  "violated_rules": [
    "G02"
  ],
  "rationale": "The request involves a state-changing operation (VACUUM) on a production table. While a change ticket exists and the change window is open, G02 mandates human review for state-changing prod operations without an APPROVED change ticket, and this operation falls under that category."
}

