  "decision": "human_review",
  "violated_rules": [
    "G04"
  ],
  "rationale": "Granting write access to a table, even in a development environment, falls under the purview of G04, which mandates human review for grants on restricted data. While the table is classified as 'public', the request involves a change to permissions, triggering the review requirement. The change ticket is pending approval, which further necessitates human review."
}

{
  "decision": "human_review",
  "violated_rules": [
    "G07"
  ],
  "rationale": "The request involves exporting non-public (confidential) data to an internal location. While the destination is an internal bucket, G07 mandates human review for confidential/restricted data exports, even to internal locations."
}

